import heapq


class RunningMedian:
    """Running median via two heaps: max-heap (negated) for the low half,
    min-heap for the high half. Sizes differ by at most 1."""

    def __init__(self):
        self._low = []   # max-heap (stored negated)
        self._high = []  # min-heap

    def add(self, x):
        if not self._low or x <= -self._low[0]:
            heapq.heappush(self._low, -x)
        else:
            heapq.heappush(self._high, x)
        # Rebalance so len(low) is equal or one greater than len(high).
        if len(self._low) > len(self._high) + 1:
            heapq.heappush(self._high, -heapq.heappop(self._low))
        elif len(self._high) > len(self._low) + 1:
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def median(self):
        if not self._low and not self._high:
            raise ValueError("median of empty stream")
        if len(self._low) == len(self._high):
            return (-self._low[0] + self._high[0]) / 2
        if len(self._low) > len(self._high):
            return -self._low[0]
        return self._high[0]

    def __len__(self):
        return len(self._low) + len(self._high)

